from batch07 import *
start('ospf','OSPF — sąsiedztwo i diagnostyka','3.4',['https://www.cisco.com/c/en/us/support/docs/ip/open-shortest-path-first-ospf/9237-9.html','https://www.cisco.com/c/en/us/support/docs/ip/open-shortest-path-first-ospf/13684-12.html'],True)
q('Kiedy 2-WAY jest normalne?','Dwa routery DROTHER na tym samym segmencie broadcast widzą się w 2-WAY. Mają FULL z DR i BDR. Co to oznacza?','Może to być prawidłowy stan',['Zawsze błąd hasła OSPF|Podane sąsiedztwa FULL i role wskazują inny kontekst.','Obowiązkowo różne MTU|2-WAY między DROTHER nie dowodzi błędu MTU.','Wymagany restart całego segmentu|Nie ma podstaw do restartu przy prawidłowym modelu sąsiedztw.'],'Na segmencie broadcast pełne sąsiedztwa nie muszą powstać między każdą parą DROTHER.')
q('Kandydat na DR','Który interfejs nie będzie kandydował na DR/BDR?','Z priorytetem OSPF równym 0',['Z priorytetem 1|To dodatnia wartość dopuszczająca wybór.','Z priorytetem 100|Dodatni wysoki priorytet nadal dopuszcza wybór.','Z priorytetem 255|To najwyższy priorytet, a nie wyłączenie kandydowania.'],'Zero usuwa interfejs z wyborów DR/BDR, nie wyłącza samego OSPF.')
c('Hello i Dead razem','Na obu końcach uzgodniono Hello 5 s i Dead 20 s. Uzupełnij konfigurację jednego końca.','R1(config-if)# ip ospf hello-interval {{b0}}\nR1(config-if)# ip ospf dead-interval {{b1}}',['5','20'],'Timery sąsiednich interfejsów muszą być zgodne; zmiana tylko jednej strony może zerwać sąsiedztwo.')
q('DR bez wywłaszczenia','Nowy router dołącza do stabilnego broadcast z wybranym DR. Ma wyższy priorytet. Czy od razu musi zostać DR?','Nie, wybór DR nie jest wywłaszczający',['Tak, zawsze natychmiast|To myli wybór z preempt znanym z HSRP.','Tak, jeśli proces ma numer 1|Lokalny numer procesu nie wymusza roli DR.','Tak, jeśli ma więcej interfejsów|Liczba interfejsów nie jest tym kryterium.'],'Wyższy priorytet ma znaczenie podczas wyboru, ale nie wypiera automatycznie działającego DR.')
c('Punkt-punkt i koszt','Na obu końcach dedykowanego Ethernet p2p uzgodniono typ point-to-point. Na R1 ustaw ten typ i jawny koszt 25.','R1(config-if)# ip ospf network {{b0}}\nR1(config-if)# ip ospf cost {{b1}}',['point-to-point','25'],'Typ point-to-point nie wybiera DR/BDR; jawny koszt zastępuje obliczany na tym interfejsie.')
q('Pierwszy wybór DR','Przy świeżym wyborze wszyscy są wzajemnie widoczni. R1 priority 100/RID 1.1.1.1, R2 priority 50/RID 9.9.9.9. Kto jest preferowany na DR?','R1',['R2, bo ma wyższy RID|Najpierw porównuje się priorytet interfejsu.','Oba jednocześnie w tej samej grupie wyboru|Prawidłowy segment ma jednego DR.','Router z krótszą nazwą|Nazwa nie jest kryterium wyboru.'],'Priorytet interfejsu ma pierwszeństwo przed router ID w wyborze DR.')
q('EXSTART i MTU','Sąsiedztwo stale pozostaje w EXSTART/EXCHANGE. Odczytano MTU 1500 i 1400. Co sprawdzić i uzgodnić?','MTU po obu stronach oraz przyczynę różnicy',['Wyłącznie nazwę procesu|Lokalna nazwa lub ID procesu nie wyjaśnia tej różnicy.','Tylko adres DNS|DNS nie negocjuje bazy OSPF.','Losowy numer VLAN bez pomiarów|To nie naprawa wykrytej niespójności MTU.'],'Niezgodne MTU mogą blokować wymianę DBD; nie należy traktować mtu-ignore jako uniwersalnej naprawy.')
q('Stan INIT','Router widzi sąsiada w INIT. Co opisuje ten etap?','Otrzymał Hello sąsiada, ale nie widzi w nim własnego RID',['Bazy są już w pełni zgodne|To odpowiada późniejszemu etapowi FULL.','Nigdy nie odebrał żadnego Hello|INIT oznacza odbiór Hello.','Trwa obowiązkowo redystrybucja BGP|To niezwiązana funkcja.'],'Brak potwierdzenia dwukierunkowości wymaga kontroli odbioru Hello i drogi powrotnej.')
c('Referencja, koszt i kontrola','W procesie 10 ustaw reference bandwidth 10000 Mb/s; na G0/0 koszt 50. Następnie pokaż sąsiadów.','R1(config)# router ospf 10\nR1(config-router)# auto-cost reference-bandwidth {{b0}}\nR1(config-router)# exit\nR1(config)# interface GigabitEthernet0/0\nR1(config-if)# ip ospf cost {{b1}}\nR1(config-if)# end\nR1# show ip ospf {{b2}}',['10000','50','neighbor'],'Referencję należy spójnie planować w domenie; jawny koszt wygrywa z jej obliczeniem na wskazanym interfejsie.')
q('Koszt obliczany','Reference bandwidth wynosi 10000 Mb/s, bandwidth interfejsu 1000 Mb/s. Brak jawnego kosztu. Jaki koszt wynika z ilorazu?','10',['1|Taki wynik nie wynika z podanych wartości.','100|To dziesięciokrotnie więcej od ilorazu.','110|110 to typowe AD OSPF, nie ten koszt.'],'10000 / 1000 = 10; AD i metryka to różne liczby.')
c('Aktywuj OSPF na porcie','Na G0/1 włącz OSPF proces 20 area 0 bez polecenia network. Ustaw też typ point-to-point, zgodny z drugim końcem.','R1(config-if)# ip ospf {{b0}} area {{b1}}\nR1(config-if)# ip ospf network {{b2}}',['20','0','point-to-point'],'Konfiguracja interfejsowa określa proces i obszar wprost; typ sieci trzeba uzgodnić między końcami.')
q('Różne obszary na łączu','R1 ma na wspólnym łączu area 0, R2 area 1. Co jest niezgodne?','Przypisanie wspólnego segmentu do obszaru',['Wyłącznie różne lokalne process ID|Same process ID mogą się różnić.','Różne adresy IP hostów routerów|Routery powinny mieć różne adresy interfejsów.','Różne hostname|Hostnames nie muszą być identyczne.'],'Sąsiedzi na wspólnym łączu OSPF muszą zgadzać się co do obszaru tego łącza.')
q('Remis w wyborze DR','Przy świeżym wyborze obaj mają priority 1. RID R1=10.0.0.1, R2=10.0.0.2. Kto jest preferowany?','R2',['R1, bo mniejszy RID wygrywa|W tym remisie preferowany jest wyższy RID.','Router z mniejszym kosztem do Internetu|Koszt domyślnej trasy nie rozstrzyga wyboru DR.','Żaden, remis blokuje wybory|Router ID rozstrzyga remis priorytetu.'],'Po równym priorytecie porównywany jest router ID.')
q('FULL a trasa do LAN','Routery są FULL, lecz brakuje konkretnego LAN-u w trasach. Co sprawdzić dalej?','Czy LAN jest objęty OSPF i co pokazują LSDB oraz tablica routingu',['Uznać, że FULL gwarantuje każdą oczekiwaną trasę|FULL opisuje sąsiedztwo, nie komplet założeń projektu.','Zmienić wszystkie router ID bez analizy|To nie celowana diagnostyka prefiksu.','Usunąć wszystkie VLAN-y|To nieuzasadniona destrukcyjna zmiana.'],'Poprawne sąsiedztwo jest warunkiem, ale nie dowodem prawidłowego ogłaszania każdej sieci.')
c('Wyklucz z wyboru DR','Na broadcast G0/2 ustaw priority 0, koszt 15 i pokaż szczegóły tego interfejsu OSPF.','R1(config-if)# ip ospf priority {{b0}}\nR1(config-if)# ip ospf cost {{b1}}\nR1(config-if)# end\nR1# show ip ospf {{b2}} GigabitEthernet0/2',['0','15','interface'],'Priority wpływa na wybór DR, koszt na obliczanie ścieżek; nie są zamienne.')
q('Dwa równe koszty','Dwie ścieżki OSPF do tego samego prefiksu mają równy koszt i są dopuszczone limitem ECMP. Co może zrobić router?','Zainstalować obie jako równokosztowe',['Zawsze odrzucić obie|Równość kosztu nie unieważnia tras.','Zawsze używać wyższego process ID sąsiada|Numer procesu sąsiada nie jest takim kryterium.','Automatycznie zmienić obie na trasy statyczne|OSPF nie zmienia ich w konfigurację statyczną.'],'ECMP umożliwia wykorzystanie równokosztowych tras; nie oznacza automatycznie przeplatania pojedynczych pakietów.')
c('Przywróć timery','Na labowym łączu broadcast oba końce mają wrócić do Hello 10 s/Dead 40 s. Ustaw na R1 i pokaż sąsiadów.','R1(config-if)# ip ospf hello-interval {{b0}}\nR1(config-if)# ip ospf dead-interval {{b1}}\nR1(config-if)# end\nR1# show ip ospf {{b2}}',['10','40','neighbor'],'Oceniaj stan po spójnej zmianie obu końców i czasie potrzebnym na odbudowę sąsiedztwa.')
q('Zmiana router ID','Na działającym procesie IOS zmieniono router-id, ale operacyjny RID nadal jest stary. Jak interpretować sytuację?','Zmiana może wymagać ponownego uruchomienia procesu w zaplanowanym oknie',['Router ID zawsze zmienia się bez wpływu na sąsiedztwa|Zmiana tożsamości może wymagać odbudowy procesu.','Numer VLAN blokuje każdą zmianę RID|Nie jest to ogólna zasada.','To dowód, że OSPF nie obsługuje jawnego RID|Jawny RID jest wspierany.'],'Konfiguracja i bieżący stan procesu mogą się różnić; reset OSPF ma wpływ na sąsiedztwa.')
end()
